package dev.homecontrol.app;

import android.app.*;
import android.graphics.Color;
import android.graphics.drawable.ColorDrawable;
import android.os.*;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.util.*;

/** Same-activity sheet: image settings do not stop/reconnect the live stream. */
final class CameraSettingsDialog extends Dialog {
    private final Activity owner;private final AppUi ui;private final String id;private JSONObject device;private LinearLayout rows;private TextView feedback;private boolean busy;private final Map<String,TextView> values=new LinkedHashMap<>();
    CameraSettingsDialog(Activity owner,AppUi ui,String id,JSONObject device){super(owner);this.owner=owner;this.ui=ui;this.id=id;this.device=device;}
    @Override protected void onCreate(Bundle state){super.onCreate(state);LinearLayout sheet=ui.column();sheet.setPadding(ui.dp(20),ui.dp(18),ui.dp(20),ui.dp(20));sheet.setBackground(ui.shape(ui.surface,24));LinearLayout heading=ui.row();heading.addView(ui.text("画面设置",18,ui.text,true),new LinearLayout.LayoutParams(0,-2,1));TextView close=ui.text("完成",14,ui.accent,true);close.setGravity(Gravity.CENTER);close.setOnClickListener(v->dismiss());heading.addView(close,new LinearLayout.LayoutParams(ui.dp(56),ui.dp(44)));sheet.addView(heading);rows=ui.column();sheet.addView(rows);feedback=ui.text("正在读取…",12,ui.muted,false);sheet.addView(feedback);ui.space(sheet,10);TextView info=ui.text("设备信息",14,ui.muted,false);info.setPadding(0,ui.dp(12),0,ui.dp(8));info.setOnClickListener(v->new AlertDialog.Builder(owner).setTitle("设备信息").setMessage(device.optString("title")+"\n"+DeviceLocation.meta(device)+"\n"+device.optString("model")).setPositiveButton("完成",null).show());sheet.addView(info);setContentView(sheet);Window window=getWindow();if(window!=null){window.setBackgroundDrawable(new ColorDrawable(Color.TRANSPARENT));window.setGravity(Gravity.BOTTOM);window.setLayout(-1,-2);}patch();refresh();}
    private void patch(){JSONArray settings=CameraSettings.items(device);if(values.isEmpty()){for(int i=0;i<settings.length();i++){JSONObject p=settings.optJSONObject(i);if(p==null)continue;String key=p.optString("key");LinearLayout row=ui.row();row.setMinimumHeight(ui.dp(56));row.setBackground(ui.ripple(ui.surface,12));row.setContentDescription(CameraSettings.title(p));row.addView(ui.text(CameraSettings.title(p),14,ui.text,false),new LinearLayout.LayoutParams(0,-2,1));TextView value=ui.text("读取中…",13,ui.muted,false);row.addView(value);row.addView(ui.icon(AppUi.RIGHT,ui.muted,16));values.put(key,value);row.setOnClickListener(v->{JSONObject current=MijiaModel.find(CameraSettings.items(device),key);if(!busy&&current!=null)edit(current);});rows.addView(row);}if(settings.length()==0)feedback.setText("暂未读取到可用的画面设置");}
        for(int i=0;i<settings.length();i++){JSONObject p=settings.optJSONObject(i);if(p==null)continue;TextView value=values.get(p.optString("key"));if(value!=null)value.setText((p.optBoolean("stale")?"上次：":"")+MijiaModel.display(p));}}
    private void refresh(){if(busy)return;busy=true;new Thread(()->{JSONObject fresh=null;String error="";try{fresh=MijiaCloud.readDevice(owner,id);}catch(Exception e){error=CloudDevices.error(e,"读取失败，已保留上次状态");}final JSONObject next=fresh;final String message=error;owner.runOnUiThread(()->{busy=false;if(!isShowing())return;if(next!=null)device=next;patch();feedback.setText(message);});},"JiaJuCameraSettingsRead").start();}
    private void edit(JSONObject p){JSONArray choices=CameraSettings.options(p);List<String> names=new ArrayList<>();List<Object> options=new ArrayList<>();for(int i=0;i<choices.length();i++){JSONObject option=choices.optJSONObject(i);if(option!=null){names.add(option.optString("description"));options.add(option.opt("value"));}}if(options.isEmpty()){Toast.makeText(owner,"该设置暂未适配",Toast.LENGTH_SHORT).show();return;}int selected=-1;for(int i=0;i<options.size();i++)if(!p.optBoolean("stale")&&MijiaValue.equivalent(options.get(i),p.opt("value")))selected=i;LinearLayout body=ui.column();final Dialog[] picker=new Dialog[1];for(int i=0;i<options.size();i++){final Object choice=options.get(i);TextView option=AppSheet.button(owner,ui,names.get(i),false);option.setOnClickListener(v->{picker[0].dismiss();if(MijiaModel.valid(p,choice))write(p.optString("key"),choice);});body.addView(option,new LinearLayout.LayoutParams(-1,ui.dp(50)));ui.space(body,6);}picker[0]=AppSheet.show(owner,CameraSettings.title(p),body,null,null);}
    private void write(String key,Object value){if(busy||MijiaModel.find(CameraSettings.items(device),key)==null)return;if(owner.getSystemService(KeyguardManager.class).isDeviceLocked()){feedback.setText("请先解锁手机");return;}busy=true;feedback.setText("正在设置…");new Thread(()->{String result;try{JSONArray array=new JSONArray().put(value);String encoded=array.toString();result=MijiaCloud.control(owner,id,key,encoded.substring(1,encoded.length()-1));}catch(Exception e){result=CloudDevices.error(e,"操作结果未确认；不会自动重复发送");}final String message=result;owner.runOnUiThread(()->{busy=false;if(!isShowing())return;feedback.setText(message);refresh();});},"JiaJuCameraSettingWrite").start();}
}
